import sys

def main():
    data = sys.stdin.read().split()
    n = int(data[0])
    nz = {}
    for i in range(n):
        v = int(data[1 + i])
        if v:
            nz[i] = v
    total = 0
    for i in range(n):
        v = int(data[1 + n + i])
        if v and i in nz:
            total += nz[i] * v
    print(total)

