def gen(rng):
    def fmt(a, b):
        return f'{len(a)}\n' + ' '.join(map(str, a)) + '\n' + ' '.join(map(str, b))
    def sparse(n, density, hi=100):
        return [rng.randint(1, hi) if rng.random() < density else 0 for _ in range(n)]
    tests = [
        fmt([0, 3, 0, 4, 0], [0, 0, 2, 6, 5]),
        fmt([1, 0, 2], [5, 9, 7]),
        fmt([0], [0]), fmt([100], [100]), fmt([0, 0, 0], [1, 2, 3]),
        fmt([1, 1, 1, 1], [1, 1, 1, 1]), fmt([0, 5, 0, 0, 7], [0, 5, 0, 0, 7]),
    ]
    for n in (2, 3, 5, 8, 12, 20, 40):
        for d in (0.2, 0.5, 1.0):
            tests.append(fmt(sparse(n, d), sparse(n, d)))
    tests.append(fmt(sparse(100000, 0.01), sparse(100000, 0.01)))
    tests.append(fmt(sparse(100000, 0.05), sparse(100000, 0.9)))
    tests.append(fmt([100] * 100000, [100] * 100000))
    tests.append(fmt(sparse(100000, 0.3), sparse(100000, 0.3)))
    return tests

